15	// DEVDESK-754 (SC2, steps 7 and 8, the pure half): the Misconfigurations tab's
16	// groups. One row per file and per fix: the key is the file, the rule
17	// (remediation.RuleKey, which folds Trivy's two spellings) and the state of the
18	// built-in fix. The count is a plain number of findings; nothing says "closed",
19	// because ctrl+o fixes one finding at a time.
20	//
21	// Hypotheses these tests freeze, for the coder to confirm or the user to overrule:
22	//   - fixGroup.Subject is the file as shown (shortPaths, inline text), fixGroup.Rule
23	//     the ID of the first member, fixGroup.Members the findings in scan order;
24	//   - a group's severity is the worst of its members';
25	//   - the key holds File, Rule and Fix apart (three fields, one comparable struct);
26	//   - a group's Command is set only when every member has the same plain command.
27	
28	// ── Fixtures ─────────────────────────────────────────────────────────────────
29	
30	const (
31		mgCrit = scan.SeverityCritical
32		mgHigh = scan.SeverityHigh
33		mgMed  = scan.SeverityMedium
34		mgLow  = scan.SeverityLow
35	)
