37	// mgFinding is a Trivy misconfiguration the way a scan records it. The message
38	// tells two instances of one rule apart.
39	func mgFinding(id, file, message string, sev scan.SeverityLevel) scan.Finding {
40		return scan.Finding{
41			ID: id, Title: "Rule " + id, Message: message, Severity: sev,
42			Source: scan.SourceTrivyMisconfig, File: file, Line: 1, EndLine: 3,
43		}
44	}
45	
46	// mgFindings are the findings of the Misconfigurations tests, interleaved on
47	// purpose so that no group is contiguous in the scan. Groups on disk, in the order
48	// the tab lists them (worst severity, most findings, file):
49	//
50	//	CRITICAL app.yaml        KSV-0003  1  No guidance available
51	//	HIGH     Dockerfile      DS002     3  Built-in fix available
52	//	HIGH     svc/Dockerfile  DS002     1  Built-in fix available
53	//	MEDIUM   deploy.yaml     KSV-0012  3  Manual (two MEDIUM, one LOW)
54	//	MEDIUM   pod.yaml        KSV-0104  1  Built-in fix unavailable: <reason>
55	//	LOW      pod.yaml        KSV-0104  1  Built-in fix available
56	func mgFindings() []scan.Finding {
57		unconfined := mgFinding("KSV-0104", "pod.yaml", "Pod 'web' sets seccomp Unconfined", mgMed)
58		unconfined.SeccompOrigin = "unconfined"
59		absent := mgFinding("KSV-0104", "pod.yaml", "Pod 'job' sets no seccomp profile", mgLow)
60		absent.SeccompOrigin = "absent"
61		return []scan.Finding{
62			mgFinding("KSV-0012", "deploy.yaml", "Container 'api' may run as root", mgMed),
63			mgFinding("DS002", "Dockerfile", "stage build", mgHigh),
64			mgFinding("DS002", "svc/Dockerfile", "svc stage", mgHigh),
65			unconfined,
66			mgFinding("DS002", "Dockerfile", "stage test", mgHigh),
67			mgFinding("KSV-0003", "app.yaml", "Default capabilities not dropped", mgCrit),
68			absent,
69			mgFinding("KSV-0012", "deploy.yaml", "Container 'sidecar' may run as root", mgMed),
70			mgFinding("DS002", "Dockerfile", "stage final", mgHigh),
71			mgFinding("KSV-0012", "deploy.yaml", "Container 'init' may run as root", mgLow),
72		}
73	}
