99	func rowsOf(groups []fixGroup) []mgRow {
100		out := make([]mgRow, 0, len(groups))
101		for _, g := range groups {
102			out = append(out, mgRow{g.Subject, g.Rule, len(g.Members), g.Status.Label()})
103		}
104		return out
105	}
