107	// groupAt is the group of file and rule whose Fix label is label.
108	func groupAt(t *testing.T, groups []fixGroup, file, rule, label string) fixGroup {
109		t.Helper()
110		for _, g := range groups {
111			if g.Subject == file && g.Rule == rule && g.Status.Label() == label {
112				return g
113			}
114		}
115		t.Fatalf("no group %s %s %q in %v", file, rule, label, rowsOf(groups))
116		return fixGroup{}
117	}
