28	// mgRescanned is the result of the same directory with the findings whose message
29	// is in gone left out, as a re-scan after a fix reports it.
30	func mgRescanned(m Model, gone ...string) *scan.Result {
31		var kept []scan.Finding
32		for _, f := range m.result.Findings {
33			if !slices.Contains(gone, f.Message) {
34				kept = append(kept, f)
35			}
36		}
37		return resultOn(m.result.Target, kept...)
38	}
