17	// handleDetailsState processes input in details state
18	func (m Model) handleDetailsState(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
19		switch msg.String() {
20		// backspace was an alias of esc, and the only one in the application.
21		case "esc":
22			m.state = m.detailsReturnState()
23			m.changePreview = changePreview{}
24			return m, nil
25		case keymap.Web:
26			return m.handleDetailsOpenReference()
27		case "enter":
28			return m.openFindingFile()
29		case writeRemediationKey:
30			return m.prepareMisconfigFix()
31		case keymap.Copy:
32			return m.copyFixCommand()
33		case keymap.Exclude:
34			return m.handleIgnoreSecret()
35		case "up":
36			m.detailsViewport.ScrollUp(1)
37		case "down":
38			m.detailsViewport.ScrollDown(1)
39		case "pgup":
40			m.detailsViewport.HalfPageUp()
41		case "pgdown":
42			m.detailsViewport.HalfPageDown()
43		case "home":
44			m.detailsViewport.GotoTop()
45		case "end":
46			m.detailsViewport.GotoBottom()
47		}
48		return m, nil
49	}
50	
51	// detailsReturnState is the level the detail was opened from: a group's list of
52	// findings when the group is still open, the results otherwise.
53	func (m Model) detailsReturnState() ViewState {
54		if m.detailsParent == StateGroup && m.openGroup != nil {
55			return StateGroup
56		}
57		return StateResults
58	}
59	
60	// handleDetailsOpenReference opens the first reference URL in the default browser.
61	func (m Model) handleDetailsOpenReference() (tea.Model, tea.Cmd) {
62		if m.selectedFinding == nil {
63			return m, nil
64		}
65		f := *m.selectedFinding
66		if len(f.References) == 0 {
67			return m, m.footer.Warn("No references available")
68		}
69		url := f.References[0]
70		return m, func() tea.Msg {
71			if err := browser.Open(url); err != nil {
72				log.Printf("ERROR [security] open URL %s: %v", url, err)
73			}
74			return nil
75		}
76	}
77	
78	// sizeDetails gives the details viewport the room the router leaves it: the
79	// view's width less the two border cells the viewport frame takes, so a line
80	// never reaches under the right border. The padding takes one more cell on each
81	// side, which is the text width (detailsTextWidth).
82	func (m *Model) sizeDetails() {
83		m.detailsViewport.SetWidth(max(m.width-2, 1))
84		m.detailsViewport.SetHeight(m.height)
85	}
86	
87	// detailsTextWidth is how many cells a line of the detail text may span: one
88	// column, never wider than maxColumnWidth.
89	func (m Model) detailsTextWidth() int { return min(max(m.width-4, 1), maxColumnWidth) }
90	
91	// scanTarget is the scanned path, for display only: it is what shortPaths cuts
92	// off a path, and an image reference there is ignored.
93	func (m Model) scanTarget() string {
94		if m.result == nil {
95			return ""
96		}
97		return m.result.Target
98	}
99	
100	// targetOnDisk says whether the scanned target is a directory, whose files a
101	// built-in fix can write.
102	func (m Model) targetOnDisk() bool {
103		return m.result != nil && m.result.TargetType == scan.TargetDirectory
104	}
105	
106	// buildDetailsContent builds the full scrollable content for the details view.
107	//
108	// What to do comes before why: the Fix block (status, Where, Do, Run, Effect),
109	// the Change it would make, then Why, the scanner's Output and the Refs. Each section is emitted only when
110	// it has something to say, and sections are joined by exactly one blank line.
111	func (m Model) buildDetailsContent() string {
112		if m.selectedFinding == nil {
113			return theme.Bg("No finding selected")
114		}
115	
116		f := *m.selectedFinding
117		t := newDetailsText(m.detailsTextWidth())
118	
119		var sections []string
120		for _, section := range [][]string{
121			m.detailsHeader(f, t),
122			m.detailsFix(f, t),
123			m.detailsChange(f, t),
124			m.detailsWhy(f, t),
125			m.detailsOutput(f, t),
126			m.detailsReferences(f, t),
127		} {
128			if len(section) > 0 {
129				sections = append(sections, strings.Join(section, "\n"))
130			}
131		}
132	
133		return lipgloss.NewStyle().
134			Padding(1).
135			Background(theme.ColorBackground).
136			Render(strings.Join(sections, "\n\n"))
137	}
138	
139	// detailsHeader is the severity and ID, then the title on one line: a title can
140	// carry a whole stderr line, and the Message below has the rest.
141	func (m Model) detailsHeader(f scan.Finding, t detailsText) []string {
142		sev := string(f.Severity)
143		header := m.getSeverityStyle(f.Severity).Render(sev) + theme.Bg(" ") +
144			theme.TitleStyle.Render(oneLine(f.ID, t.width-ansi.StringWidth(sev)-1))
145		title := oneLine(shortPaths(f.Title, m.scanTarget()), t.width)
146		return []string{header, t.text.Render(title)}
147	}
148	
149	// detailsFix is the Fix block: the status in words, then, with no blank line
150	// between them, where the finding is, what to do, the command to run and what the
151	// fix does. It is written in ColorText alone (DEVDESK-751, AC7): ColorDim, the
152	// sub-title and the warning colours fall under 4.5:1 on several shipped themes,
153	// so the word "Warning:" carries the warning.
154	func (m Model) detailsFix(f scan.Finding, t detailsText) []string {
155		status := m.fixStatus(f)
156		lines := t.field("Fix: ", status.Label(), t.text)
157		lines = append(lines, m.detailsWhere(f, t)...)
158		lines = append(lines, t.list("Do: ", fixSteps(f), f.Resolution, t.text)...)
159		lines = append(lines, detailsRun(f, t)...)
160		lines = append(lines, detailsRepro(f, t)...)
161		lines = append(lines, t.field("Effect: ", status.Effect, t.text)...)
162		return append(lines, t.field("Warning: ", status.Warning, t.text)...)
163	}
164	
165	// detailsWhere is the facts that place the finding, one per line: the file under
166	// the label Where, then the package, job, script and match under their own. The
167	// labels start in one column and the values in another, so a value that wraps
168	// hangs under the values. With no file, the first fact takes the label Where.
169	func (m Model) detailsWhere(f scan.Finding, t detailsText) []string {
170		facts := whereFacts(f, m.scanTarget())
171		labels := make([]string, len(facts))
172		room := 0
173		for i, fc := range facts {
174			labels[i] = fc.Label + ": "
175			if i == 0 {
176				labels[i] = "Where: "
177			}
178			room = max(room, ansi.StringWidth(labels[i]))
179		}
180		var lines []string
181		for i, fc := range facts {
182			label := labels[i] + strings.Repeat(" ", room-ansi.StringWidth(labels[i]))
183			lines = append(lines, t.field(label, fc.Value, t.text)...)
184		}
185		return lines
186	}
187	
188	// detailsRun is the command on one line, cut when it is wider than the column:
189	// the copy key puts the whole of it on the clipboard.
190	func detailsRun(f scan.Finding, t detailsText) []string {
191		const label = "Run: "
192		cmd, ok := runCommand(f)
193		if !ok {
194			return nil
195		}
196		return []string{t.heading(label) + t.text.Render(oneLine("$ "+cmd, t.width-ansi.StringWidth(label)))}
197	}
198	
199	// detailsWhy is the reason the finding matters: the scanner's description, the
200	// Pod Security profile, where the finding comes from and its type.
201	func (m Model) detailsWhy(f scan.Finding, t detailsText) []string {
202		var lines []string
203		if strings.TrimSpace(f.Description) != "" {
204			lines = t.block(f.Description, t.text)
205		}
206		lines = append(lines, t.field("Pod Security: ", pssLabel(f), t.text)...)
207		lines = append(lines, t.field("Source: ", f.Source, t.text)...)
208		lines = append(lines, t.field("Type: ", f.IaCType, t.text)...)
209		if len(lines) == 0 {
210			return nil
211		}
212		return append([]string{t.heading("Why:")}, lines...)
213	}
214	
215	// detailsOutput is what the scanner said about this instance, capped: the start
216	// of it is what tells two findings of one rule apart, and the rest is in the log.
217	// A message that only repeats the title or the description adds nothing.
218	func (m Model) detailsOutput(f scan.Finding, t detailsText) []string {
219		msg := strings.TrimSpace(f.Message)
220		if msg == "" || msg == strings.TrimSpace(f.Title) || msg == strings.TrimSpace(f.Description) {
221			return nil
222		}
223		lines, hidden := cappedLines(dropBlankLines(shortPaths(msg, m.scanTarget())), t.width, maxMessageLines)
224		if len(lines) == 0 {
225			return nil
226		}
227		out := []string{t.heading("Output:")}
228		for _, line := range lines {
229			out = append(out, t.text.Render(line))
230		}
231		if more := moreLines(hidden); more != "" {
232			out = append(out, theme.DimStyle.Render(more))
233		}
234		return out
235	}
236	
237	// detailsReferences are the reference URLs, one per line.
238	func (m Model) detailsReferences(f scan.Finding, t detailsText) []string {
239		if len(f.References) == 0 {
240			return nil
241		}
242		lines := []string{t.heading("Refs:")}
243		for _, ref := range f.References {
244			lines = append(lines, t.indented("  ", ref, t.text)...)
245		}
246		return lines
247	}
248	
249	// renderDetailsView renders the scrollable details viewport.
250	func (m Model) renderDetailsView() string {
251		return m.detailsViewport.View()
252	}
253	
254	// getSeverityStyle returns style for severity level (Rule 102: the palette
255	// lives in the theme, not here).
256	func (m Model) getSeverityStyle(sev scan.SeverityLevel) lipgloss.Style {
257		return theme.SeverityTextStyle(string(sev))
258	}
259	
260	// HeaderView interface implementation
261	
262	// packageKind says what has to move to clear a vulnerability, from the class
263	// Trivy reported. Empty for a result cached before the class was recorded: it
264	// is unknown, and is not shown rather than guessed.
265	func packageKind(class string) string {
266		switch class {
267		case scan.ClassOSPackages:
268			return "Base image package"
269		case scan.ClassLangPackages:
270			return "Application dependency"
271		}
272		return ""
273	}
