1	package security
2	
3	import (
4		"path/filepath"
5		"strconv"
6		"strings"
7	
8		"github.com/anthnel/devdesk/internal/remediation"
9		"github.com/anthnel/devdesk/internal/scan"
10		"github.com/anthnel/devdesk/internal/ui/shortcut"
11	)
12	
13	// fixState is the state behind the Fix line of a finding detail (DEVDESK-751).
14	type fixState int
15	
16	const (
17		fixManual fixState = iota
18		fixBuiltIn
19		fixBuiltInDeclined
20		fixNoFixPublished
21		fixCannotFixHere
22		fixNoGuidance
23	)
24	
25	// The closed vocabulary of the Fix line (AC1). Only labelBuiltInUnavailable
26	// carries a reason, which Label appends after a colon.
27	const (
28		labelBuiltInAvailable   = "Built-in fix available"
29		labelBuiltInUnavailable = "Built-in fix unavailable"
30		labelManual             = "Manual"
31		labelNoFixPublished     = "No fix published"
32		labelCannotFixHere      = "Cannot fix here"
33		labelNoGuidance         = "No guidance available"
34	)
35	
36	// Reasons a finding's file cannot be opened from the detail (Rule 130).
37	const (
38		reasonFileOutsideTarget = "This file is outside the scanned directory"
39		reasonNoFile            = "This finding names no file"
40		// reasonFileLinkOutsideTarget is the answer of enter, which follows links:
41		// the header cannot know it (it reads no disk).
42		reasonFileLinkOutsideTarget = "This file is reached through a link that leaves the scanned directory"
43	)
44	
45	// fixStatus is the Fix line of a finding detail, in words: a colour or a key
46	// name alone would not say it (Rule 134), so the status never names a key.
47	type fixStatus struct {
48		State   fixState
49		Reason  string // why the built-in fix is unavailable or cannot run here
50		Effect  string // what the fix does: the catalog rule's title, or "Fixed in <v>"
51		Warning string // remediation.Rule.Warning, or ""
52	}
53	
54	// Label is the closed-vocabulary text of the status.
55	func (s fixStatus) Label() string {
56		switch s.State {
57		case fixBuiltIn:
58			return labelBuiltInAvailable
59		case fixBuiltInDeclined:
60			return labelBuiltInUnavailable + ": " + s.Reason
61		case fixManual:
62			return labelManual
63		case fixNoFixPublished:
64			return labelNoFixPublished
65		case fixCannotFixHere:
66			return labelCannotFixHere
67		}
68		return labelNoGuidance
69	}
70	
71	// fixStatusOf says whether f can be fixed and why not. For a misconfiguration
72	// it reads misconfigFixAvailability, the computation behind the shortcut column,
73	// so the detail and the header agree (Rule 130).
74	func fixStatusOf(f scan.Finding, onDisk bool) fixStatus {
75		switch scan.Categorize(f) {
76		case scan.CategoryMisconfiguration:
77			return misconfigFixStatus(f, onDisk)
78		case scan.CategoryVulnerability:
79			if f.FixedIn != "" {
80				return fixStatus{State: fixManual, Effect: "Fixed in " + f.FixedIn}
81			}
82			return fixStatus{State: fixNoFixPublished}
83		}
84		return guidanceStatus(f)
85	}
86	
87	// misconfigFixStatus is the status of a misconfiguration, in the order of
88	// misconfigFixAvailability: an image first, then the catalog, then the guidance
89	// a finding the catalog does not know can still carry.
90	func misconfigFixStatus(f scan.Finding, onDisk bool) fixStatus {
91		rule, a := misconfigFixAvailability(f, onDisk)
92		switch {
93		case !onDisk:
94			return fixStatus{State: fixCannotFixHere, Reason: a.Reason}
95		case a.Enabled():
96			return fixStatus{State: fixBuiltIn, Effect: rule.Title, Warning: rule.Warning}
97		case rule.AVDID != "":
98			return fixStatus{State: fixBuiltInDeclined, Reason: a.Reason}
99		}
100		return guidanceStatus(f)
101	}
102	
103	// guidanceStatus is Manual when the finding tells how to fix it by hand, and
104	// No guidance available when it does not.
105	func guidanceStatus(f scan.Finding) fixStatus {
106		if hasGuidance(f) {
107			return fixStatus{State: fixManual}
108		}
109		return fixStatus{State: fixNoGuidance}
110	}
111	
112	// hasGuidance says whether f carries any instruction: a Resolution, Steps, a
113	// FixCommand or a remediation.MissingFor text.
114	func hasGuidance(f scan.Finding) bool {
115		if f.Resolution != "" || f.FixCommand != "" || len(f.Steps) > 0 {
116			return true
117		}
118		_, ok := remediation.MissingFor(f)
119		return ok
120	}
121	
122	// runCommand is the text under Run and the text Y copies: the FixCommand trimmed,
123	// when fixAction calls it a command and it is plain words. One computation, two
124	// readers.
125	//
126	// The command is pasted into a shell, and its names and versions come from a
127	// scan, so anything but words is refused (DEVDESK-751): a line break, a control
128	// character (an escape sequence, a tab, a carriage return), a blank other than a
129	// single space, a character that has no visible form (a zero-width or
130	// right-to-left mark) or a shell metacharacter. A refused command is not lost:
131	// fixSteps shows its text under Do.
132	func runCommand(f scan.Finding) (string, bool) {
133		label, text := fixAction(f)
134		cmd := strings.TrimSpace(text)
135		if label != "Run" || cmd == "" || !scan.PlainWords(cmd) {
136			return "", false
137		}
138		return cmd, true
139	}
140	
141	// fixSteps are the numbered steps under Do: the steps DevDesk wrote for the
142	// finding (Steps, first), what a rule the catalog cannot fix is missing, and a
143	// FixCommand that is not offered under Run: a sentence rather than a command, or
144	// a command runCommand refuses.
145	func fixSteps(f scan.Finding) []string {
146		steps := append([]string(nil), f.Steps...)
147		if _, inCatalog := remediation.FixFor(f); !inCatalog {
148			if text, ok := remediation.MissingFor(f); ok {
149				steps = append(steps, text)
150			}
151		}
152		if _, offered := runCommand(f); !offered {
153			if _, text := fixAction(f); strings.TrimSpace(text) != "" {
154				steps = append(steps, text)
155			}
156		}
157		return steps
158	}
159	
160	// fact is one labelled value of the Where section.
161	type fact struct{ Label, Value string }
162	
163	// whereFacts are the facts under Where, in order: File, Package, Job, Script,
164	// Match. A path is shown the way shortPaths shows it, with its line.
165	func whereFacts(f scan.Finding, target string) []fact {
166		var facts []fact
167		add := func(label, value string) {
168			if value != "" {
169				facts = append(facts, fact{label, value})
170			}
171		}
172		file := shortPaths(f.File, target)
173		if file != "" && f.Line > 0 {
174			file += ":" + strconv.Itoa(f.Line)
175		}
176		add("File", file)
177		add("Package", packageFact(f))
178		add("Job", f.Job)
179		add("Script", f.ScriptLine)
180		add("Match", f.Match)
181		return facts
182	}
183	
184	// packageFact is "name version (kind)", leaving out what is unknown.
185	func packageFact(f scan.Finding) string {
186		if f.PkgName == "" {
187			return ""
188		}
189		out := f.PkgName
190		if f.Version != "" {
191			out += " " + f.Version
192		}
193		if kind := packageKind(f.Class); kind != "" {
194			out += " (" + kind + ")"
195		}
196		return out
197	}
198	
199	// findingFilePath is the absolute path of the finding's file under the scanned
200	// directory, or the reason it cannot be opened. It does no I/O: whether the file
201	// exists is for the viewer to say (Rule 130, "Not knowing"). A path that leaves
202	// the target, by a parent segment or an absolute path elsewhere, is refused.
203	func findingFilePath(f scan.Finding, target string, onDisk bool) (string, shortcut.Availability) {
204		if !onDisk {
205			return "", shortcut.Unavailable(reasonFileNotOnDisk)
206		}
207		if f.File == "" {
208			return "", shortcut.Unavailable(reasonNoFile)
209		}
210		root := filepath.Clean(target)
211		file := filepath.ToSlash(f.File)
212		var path string
213		switch {
214		case file == scanMount || strings.HasPrefix(file, scanMount+"/"):
215			path = filepath.Join(root, filepath.FromSlash(strings.TrimPrefix(file, scanMount)))
216		case filepath.IsAbs(f.File):
217			path = filepath.Clean(f.File)
218		default:
219			path = filepath.Join(root, filepath.FromSlash(file))
220		}
221		rel, err := filepath.Rel(root, path)
222		if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
223			return "", shortcut.Unavailable(reasonFileOutsideTarget)
224		}
225		return path, shortcut.Availability{}
226	}
227	
228	// sameFinding says whether a and b are one finding across a re-scan: the line
229	// is not compared, the fix itself moves it.
230	func sameFinding(a, b scan.Finding) bool {
231		return a.Source == b.Source &&
232			remediation.RuleKey(a.ID) == remediation.RuleKey(b.ID) &&
233			a.File == b.File && a.PkgName == b.PkgName && a.Version == b.Version &&
234			instanceOf(a) == instanceOf(b)
235	}
236	
237	// fixAction says how to show f.FixCommand: ("Run", cmd) for a real command,
238	// ("", instruction) for a sentence such as "Update pkg to 1.2", ("", "") when
239	// there is none.
240	func fixAction(f scan.Finding) (label, text string) {
241		switch {
242		case f.FixCommand == "":
243			return "", ""
244		case scan.IsFixInstruction(f):
245			return "", f.FixCommand
246		}
247		return "Run", f.FixCommand
248	}
