139	// detailsHeader is the severity and ID, then the title on one line: a title can
140	// carry a whole stderr line, and the Message below has the rest.
141	func (m Model) detailsHeader(f scan.Finding, t detailsText) []string {
142		sev := string(f.Severity)
143		header := m.getSeverityStyle(f.Severity).Render(sev) + theme.Bg(" ") +
144			theme.TitleStyle.Render(oneLine(f.ID, t.width-ansi.StringWidth(sev)-1))
145		title := oneLine(shortPaths(f.Title, m.scanTarget()), t.width)
146		return []string{header, t.text.Render(title)}
147	}
148	
149	// detailsFix is the Fix block: the status in words, then, with no blank line
150	// between them, where the finding is, what to do, the command to run and what the
151	// fix does. It is written in ColorText alone (DEVDESK-751, AC7): ColorDim, the
152	// sub-title and the warning colours fall under 4.5:1 on several shipped themes,
153	// so the word "Warning:" carries the warning.
154	func (m Model) detailsFix(f scan.Finding, t detailsText) []string {
155		status := m.fixStatus(f)
156		lines := t.field("Fix: ", status.Label(), t.text)
157		lines = append(lines, m.detailsWhere(f, t)...)
158		lines = append(lines, t.list("Do: ", fixSteps(f), f.Resolution, t.text)...)
159		lines = append(lines, detailsRun(f, t)...)
160		lines = append(lines, detailsRepro(f, t)...)
161		lines = append(lines, t.field("Effect: ", status.Effect, t.text)...)
162		return append(lines, t.field("Warning: ", status.Warning, t.text)...)
163	}
164	
165	// detailsWhere is the facts that place the finding, one per line: the file under
166	// the label Where, then the package, job, script and match under their own. The
167	// labels start in one column and the values in another, so a value that wraps
168	// hangs under the values. With no file, the first fact takes the label Where.
169	func (m Model) detailsWhere(f scan.Finding, t detailsText) []string {
170		facts := whereFacts(f, m.scanTarget())
171		labels := make([]string, len(facts))
172		room := 0
173		for i, fc := range facts {
174			labels[i] = fc.Label + ": "
175			if i == 0 {
176				labels[i] = "Where: "
177			}
178			room = max(room, ansi.StringWidth(labels[i]))
179		}
180		var lines []string
181		for i, fc := range facts {
182			label := labels[i] + strings.Repeat(" ", room-ansi.StringWidth(labels[i]))
183			lines = append(lines, t.field(label, fc.Value, t.text)...)
184		}
185		return lines
186	}
187	
188	// detailsRun is the command on one line, cut when it is wider than the column:
189	// the copy key puts the whole of it on the clipboard.
190	func detailsRun(f scan.Finding, t detailsText) []string {
191		const label = "Run: "
192		cmd, ok := runCommand(f)
193		if !ok {
194			return nil
195		}
196		return []string{t.heading(label) + t.text.Render(oneLine("$ "+cmd, t.width-ansi.StringWidth(label)))}
197	}
198	
199	// detailsWhy is the reason the finding matters: the scanner's description, the
200	// Pod Security profile, where the finding comes from and its type.
201	func (m Model) detailsWhy(f scan.Finding, t detailsText) []string {
202		var lines []string
203		if strings.TrimSpace(f.Description) != "" {
204			lines = t.block(f.Description, t.text)
205		}
206		lines = append(lines, t.field("Pod Security: ", pssLabel(f), t.text)...)
207		lines = append(lines, t.field("Source: ", f.Source, t.text)...)
208		lines = append(lines, t.field("Type: ", f.IaCType, t.text)...)
209		if len(lines) == 0 {
210			return nil
211		}
212		return append([]string{t.heading("Why:")}, lines...)
213	}
214	
215	// detailsOutput is what the scanner said about this instance, capped: the start
216	// of it is what tells two findings of one rule apart, and the rest is in the log.
217	// A message that only repeats the title or the description adds nothing.
218	func (m Model) detailsOutput(f scan.Finding, t detailsText) []string {
219		msg := strings.TrimSpace(f.Message)
220		if msg == "" || msg == strings.TrimSpace(f.Title) || msg == strings.TrimSpace(f.Description) {
221			return nil
222		}
223		lines, hidden := cappedLines(dropBlankLines(shortPaths(msg, m.scanTarget())), t.width, maxMessageLines)
224		if len(lines) == 0 {
225			return nil
226		}
227		out := []string{t.heading("Output:")}
228		for _, line := range lines {
229			out = append(out, t.text.Render(line))
230		}
231		if more := moreLines(hidden); more != "" {
232			out = append(out, theme.DimStyle.Render(more))
233		}
234		return out
235	}
236	
237	// detailsReferences are the reference URLs, one per line.
238	func (m Model) detailsReferences(f scan.Finding, t detailsText) []string {
239		if len(f.References) == 0 {
240			return nil
241		}
242		lines := []string{t.heading("Refs:")}
243		for _, ref := range f.References {
244			lines = append(lines, t.indented("  ", ref, t.text)...)
245		}
246		return lines
247	}
