86	// ── Availability ─────────────────────────────────────────────────────────────
87	
88	// canFixMisconfig is the one computation behind the shortcut column and the
89	// handler (Rule 130). It answers in the order the user would ask: am I in the
90	// right place, is there a row, can its file be written at all, and is this rule
91	// one the catalog knows.
92	//
93	// The last question runs the fix itself. That is deliberate: a rule can be in
94	// the catalog and still decline this instance — a base image whose distribution
95	// cannot be identified, a stage that already sets a user — and greying out on
96	// "the catalog has an entry" while the handler then refuses would be exactly
97	// the two computations Rule 130 forbids.
98	func (m Model) canFixMisconfig() shortcut.Availability {
99		if m.activeTab != TabMisconfig {
100			return shortcut.Unavailable(reasonNotMisconfigTab)
101		}
102		f, ok := m.subjectFinding()
103		if !ok {
104			return shortcut.Unavailable(reasonNoFinding)
105		}
106		if _, a := misconfigFixAvailability(f, m.targetOnDisk()); !a.Enabled() {
107			return a
108		}
109		// What the stored preview knows, with no disk read (DEVDESK-753).
110		return m.previewVerdict(f)
111	}
112	
113	// misconfigFixAvailability is what canFixMisconfig answers for a finding once a
114	// row exists, and what the finding detail reads for its fix status, so the two
115	// cannot disagree (Rule 130). onDisk says whether the target is a directory:
116	// an image's files are inside it, where nothing can be written. It also returns
117	// the catalog rule, whenever the catalog has one, so a caller can say what the
118	// fix would do even where it cannot run.
119	func misconfigFixAvailability(f scan.Finding, onDisk bool) (remediation.Rule, shortcut.Availability) {
120		rule, ok := remediation.FixFor(f)
121		if !onDisk {
122			return rule, shortcut.Unavailable(reasonFileNotOnDisk)
123		}
124		if !ok {
125			return rule, shortcut.Unavailable(noFixReason(f))
126		}
127		// A refusal the finding alone settles (DEVDESK-688): greyed in advance, with
128		// the reason the press of the key would give.
129		if rule.Declines != nil {
130			if reason := rule.Declines(f); reason != "" {
131				return rule, shortcut.Unavailable(reason)
132			}
133		}
134		// Reading the file here would be I/O on a path the header calls every
135		// frame, so the declines that need the content are left to the Cmd and
136		// reach the footer. What is settled here is everything the finding alone
137		// can answer.
138		return rule, shortcut.Availability{}
139	}
140	
141	// noFixReason is why a finding with no fix in the catalog is refused: for a Pod
142	// Security finding, what the manifest is missing (DEVDESK-689); for anything
143	// else, the generic refusal. The fix is tried first, so a rule that has one never
144	// reaches the missing text.
145	func noFixReason(f scan.Finding) string {
146		if text, ok := remediation.MissingFor(f); ok {
147			return text
148		}
149		return remediation.ReasonNoFixForRule
150	}
