475	// handleMisconfigVerified reports the verdict, and swaps in the result it was
476	// read from.
477	//
478	// The swap is what keeps the screen from contradicting the footer: without it a
479	// line saying the rule is gone would sit above a table still listing it.
480	func (m Model) handleMisconfigVerified(msg MisconfigVerifiedMsg) (tea.Model, tea.Cmd) {
481		if msg.Target != m.targetPath {
482			return m, nil
483		}
484		m.misconfigVerifying = nil
485		// The file was rewritten whatever the re-scan managed to say: the detail
486		// that is still open asks for its change again (DEVDESK-753).
487		if msg.Err != nil {
488			log.Printf("ERROR [security/misconfig] verify %s: %s", msg.Rule, withoutPath(msg.Err))
489			return m, tea.Batch(m.restartChangePreview(), m.footer.Error("Could not read the verification scan — check logs"))
490		}
491		if msg.Result != nil {
492			m.setResult(msg.Result)
493		}
494		preview := m.restartChangePreview()
495		verdict := m.verdictFooter(msg)
496		return m, tea.Batch(preview, verdict)
497	}
