499	// verdictFooter sets the footer to what the re-scan found, and returns its timer.
500	func (m *Model) verdictFooter(msg MisconfigVerifiedMsg) tea.Cmd {
501		msg.File = shownName(msg.File)
502		if !msg.Cleared {
503			// Not a failure: the file was written, and the rule still fires. Saying
504			// so is the only honest answer, and it is why the scan exists.
505			ids := msg.Still
506			if len(ids) == 0 {
507				ids = []string{msg.Rule}
508			}
509			return m.footer.Warn(fmt.Sprintf("%s still reported in %s after the fix", strings.Join(ids, " and "), msg.File))
510		}
511		if len(msg.Scope.Rules) > 0 {
512			return m.footer.Info(fmt.Sprintf("%s cleared for the whole pod in %s — confirmed by a re-scan",
513				strings.Join(msg.Scope.Rules, " and "), msg.File))
514		}
515		return m.footer.Info(fmt.Sprintf("%s cleared in %s — confirmed by a re-scan", msg.Rule, msg.File))
516	}
